wiggle(frq, amp);

let frq = 1.5;
let amp = 30;
let seed = 1;
seedRandom(seed, true);
wiggle(frq, amp);

let type = "cycle";
let numKeys = 0;
loopOut(type, numKeys);

let type = "pingpong";
let numKeys = 0;
loopOut(type, numKeys);

let amp = 0.1;
let freq = 2.0;
let decay = 2.0;
let n = 0;
if (numKeys > 0) {
  n = nearestKey(time).index;
  if (key(n).time > time) n--;
}
if (n == 0) { t = 0; } else { t = time - key(n).time; }
if (n > 0) {
  let v = velocityAtTime(key(n).time - thisComp.frameDuration/10);
  value + v*amp*Math.sin(freq*t*2*Math.PI)/Math.exp(decay*t);
} else {
  value;
}

let freq = 3;
let decay = 5;
let n = 0;
if (numKeys > 0) {
  n = nearestKey(time).index;
  if (key(n).time > time) n--;
}
if (n > 0) {
  let t = time - key(n).time;
  let amp = velocityAtTime(key(n).time - thisComp.frameDuration/10);
  let w = freq*Math.PI*2;
  value + amp*(Math.sin(t*w)/Math.exp(decay*t)/w);
} else {
  value;
}

let tIn = 0;
let tOut = 1;
let vIn = 0;
let vOut = 100;
linear(time, tIn, tOut, vIn, vOut);

let tIn = 0;
let tOut = 1;
let vIn = 0;
let vOut = 100;
ease(time, tIn, tOut, vIn, vOut);

let lo = 0;
let hi = 100;
clamp(value, lo, hi);
